-- Hard cases for tools/pg_erd/pg_erd.sql. Expectations are written by hand in tests/test_pg_erd.py.
create schema edge;
create schema edge2;
set search_path to edge;

-- composite PK, identity always, a unique whose column order differs from the table's
create table accounts (
  tenant_id int not null,
  account_id int generated always as identity,
  name text not null,
  code text not null,
  primary key (tenant_id, account_id),
  constraint accounts_code_key unique (code, tenant_id)
);
comment on table accounts is '[reference] 계정';
comment on column accounts.name is '이름 <b>굵게</b>';

-- composite FK with cascade, composite self FK, serial, stored generated, single- and multi-column checks
create table orders (
  tenant_id int not null,
  order_id serial,
  account_id int not null,
  parent_order_id int,
  qty int not null constraint orders_qty_check check (qty > 0),
  price numeric(10,2) not null default 0,
  total numeric(12,2) generated always as (qty * price) stored,
  status text not null default 'new',
  primary key (tenant_id, order_id),
  constraint orders_account_fkey foreign key (tenant_id, account_id) references accounts (tenant_id, account_id) on delete cascade,
  constraint orders_parent_fkey foreign key (tenant_id, parent_order_id) references orders (tenant_id, order_id),
  constraint orders_price_check check (price >= 0 or status = 'void')
);
create unique index orders_open_one on orders (tenant_id, account_id) where status = 'open';
create index orders_lower_status on orders (lower(status));

-- mutual FKs
create table teams (team_id int primary key, lead_id int);
create table members (member_id int primary key, team_id int not null constraint members_team_fkey references teams);
alter table teams add constraint teams_lead_fkey foreign key (lead_id) references members (member_id);

-- no primary key
create table audit_log (at timestamptz not null default now(), message text);

-- partitioned table with two partitions, an FK out of it and an FK into it
create table events (
  event_id bigint generated by default as identity,
  happened_on date not null,
  account_tenant int not null,
  account_id int not null,
  primary key (event_id, happened_on),
  constraint events_account_fkey foreign key (account_tenant, account_id) references accounts (tenant_id, account_id)
) partition by range (happened_on);
create table events_2025 partition of events for values from ('2025-01-01') to ('2026-01-01');
create table events_2026 partition of events for values from ('2026-01-01') to ('2027-01-01');
create table event_notes (
  note_id int primary key,
  event_id bigint not null,
  happened_on date not null,
  constraint event_notes_event_fkey foreign key (event_id, happened_on) references events (event_id, happened_on)
);

-- a view and a materialized view
create view open_orders as
  select o.order_id, a.name from orders o join accounts a using (tenant_id, account_id) where o.status = 'open';
create materialized view order_counts as select account_id, count(*) as n from orders group by account_id;

-- names and comments that must come back byte for byte and never run as HTML
create table "weird ""name""" ("<img src=x onerror=alert(1)>" text, id int primary key);
comment on table "weird ""name""" is '<img src=x onerror="document.body.dataset.pwned=1"> </script><script>document.body.dataset.pwned=2</script>';

-- the same table name in two schemas, with an FK from one to the other
create table edge.dup (id int primary key);
create table edge2.dup (id int primary key, edge_dup_id int constraint dup_edge_fkey references edge.dup (id));
